template.value:
vertex $RETURN_TYPE$ $NAME$(
    $VERTEX_IN$ in [[stage_in]],
    constant $MATRIX_TYPE$& mvpMatrix [[buffer(0)]]
) {
    $RETURN_TYPE$ out;
    $END$
    return out;
}

kernel void $NAME$(
    texture2d<$TYPE$, access::read> inTexture [[texture(0)]],
    texture2d<$TYPE$, access::write> outTexture [[texture(1)]],
    uint2 gid [[thread_position_in_grid]]
) {
    if (gid.x >= outTexture.get_width() || gid.y >= outTexture.get_height()) {
        return;
    }

    $TYPE$4 color = inTexture.read(gid);
    $END$
    outTexture.write(color, gid);
}

kernel void $NAME$Kernel(
    texture2d<float, access::write> outputTexture [[texture(0)]],
    instance_acceleration_structure accelerationStructure [[buffer(0)]],
    constant float3& rayOrigin [[buffer(1)]],
    constant float3& rayDirection [[buffer(2)]],
    uint2 gid [[thread_position_in_grid]]
) {
    if (gid.x >= outputTexture.get_width() || gid.y >= outputTexture.get_height()) {
        return;
    }

    Ray ray;
    ray.origin = rayOrigin;
    ray.direction = rayDirection;
    ray.minDistance = 0.0;
    ray.maxDistance = 1000.0;

    intersector<triangle_data, instancing> intersector;
    auto intersection = intersector.intersect(ray, accelerationStructure, RAY_MASK_ALL);

    $END$

    float3 color = float3(1.0);
    outputTexture.write(float4(color, 1.0), gid);
}

[[object, max_total_threadgroups_per_mesh_grid($MAX_GROUPS$)]]
void $NAME$(
    object_data $PAYLOAD$& payload [[payload]],
    constant SceneData& sceneData [[buffer(0)]],
    uint threadId [[thread_position_in_grid]],
    mesh_grid_properties meshGridProps
) {
    $END$

    if (threadId == 0) {
        meshGridProps.set_threadgroups_per_grid(uint3(1, 1, 1));
    }
}

using MeshOutput = mesh<$VERTEX$, $PRIMITIVE$, $MAX_VERTS$, $MAX_PRIMS$, topology::triangle>;

[[mesh, max_total_threads_per_threadgroup($THREADS$)]]
void $NAME$(
    MeshOutput output,
    uint meshletId [[threadgroup_position_in_grid]],
    uint threadId [[thread_position_in_threadgroup]]
) {
    if (threadId == 0) {
        output.set_vertex_count($MAX_VERTS$);
        output.set_primitive_count($MAX_PRIMS$);
    }

    $END$
}
